inline void DF_init(DF_Sha* s){ s->h[0]=0x6a09e667;s->h[1]=0xbb67ae85;s->h[2]=0x3c6ef372;s->h[3]=0xa54ff53a;s->h[4]=0x510e527f;s->h[5]=0x9b05688c;s->h[6]=0x1f83d9ab;s->h[7]=0x5be0cd19; s->len=0; s->bl=0; }
inline void DF_block(DF_Sha* s){ uint32_t w[64]; for(int i=0;i<16;i++) w[i]=(s->buf[i*4]<<24)|(s->buf[i*4+1]<<16)|(s->buf[i*4+2]<<8)|s->buf[i*4+3]; for(int i=16;i<64;i++){uint32_t s0=DF_RR(w[i-15],7)^DF_RR(w[i-15],18)^(w[i-15]>>3),s1=DF_RR(w[i-2],17)^DF_RR(w[i-2],19)^(w[i-2]>>10); w[i]=w[i-16]+s0+w[i-7]+s1;} uint32_t a=s->h[0],b=s->h[1],c=s->h[2],d=s->h[3],e=s->h[4],f=s->h[5],g=s->h[6],h=s->h[7]; for(int i=0;i<64;i++){uint32_t S1=DF_RR(e,6)^DF_RR(e,11)^DF_RR(e,25),ch=(e&f)^(~e&g),t1=h+S1+ch+DF_K[i]+w[i],S0=DF_RR(a,2)^DF_RR(a,13)^DF_RR(a,22),mj=(a&b)^(a&c)^(b&c),t2=S0+mj; h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;} s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h; s->bl=0; }
inline void DF_update(DF_Sha* s,const unsigned char* d,unsigned l){ s->len+=l; while(l--){ s->buf[s->bl++]=*d++; if(s->bl==64) DF_block(s); } }
